    print(f"\nString {idx}: '{inp}' -> '{outp}'")

    # Find positions where they differ
    min_len = min(len(inp), len(outp))
    diff_positions = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_positions.append(j)

    if len(outp) > len(inp):
        # Extension at the end
        diff_positions.extend(range(len(inp), len(outp)))
